//! Shared pure-Rust CPU reference pipeline for golden testing and headless verification.

use std::io::Cursor;

use glam::Vec3;
use rraw_core::{BayerOrigin, CfaColor, CfaPattern, Recipe, SignedCfaBuffer};

use crate::drt::apply_agx_edr;
use crate::gamut_guard::apply_gamut_guard_ap1;
use crate::ColorError;

/// Continuous RGB floating-point image generated by the CPU reference pipeline.
#[derive(Debug, Clone, PartialEq)]
pub struct CpuRgbImage {
    width: usize,
    height: usize,
    pixels: Vec<[f32; 3]>,
}

impl CpuRgbImage {
    /// Creates a new CPU RGB image buffer, verifying length equality.
    pub fn new(width: usize, height: usize, pixels: Vec<[f32; 3]>) -> Result<Self, ColorError> {
        let expected = width.checked_mul(height).ok_or(ColorError::Core(
            rraw_core::CoreError::InvalidDimensions { width, height },
        ))?;

        if pixels.len() != expected {
            return Err(ColorError::Core(
                rraw_core::CoreError::BufferLengthMismatch {
                    expected,
                    actual: pixels.len(),
                },
            ));
        }

        Ok(Self {
            width,
            height,
            pixels,
        })
    }

    /// Image width in pixels.
    #[must_use]
    pub const fn width(&self) -> usize {
        self.width
    }

    /// Image height in pixels.
    #[must_use]
    pub const fn height(&self) -> usize {
        self.height
    }

    /// Returns the RGB sample at `(x, y)`.
    #[must_use]
    pub fn pixel(&self, x: usize, y: usize) -> [f32; 3] {
        if x < self.width && y < self.height {
            self.pixels[y * self.width + x]
        } else {
            [0.0, 0.0, 0.0]
        }
    }

    /// Encodes image to 16-bit RGB PNG format bytes in memory.
    pub fn to_png_16bit_bytes(&self) -> Result<Vec<u8>, ColorError> {
        let mut buffer = Vec::new();
        {
            let mut encoder = png::Encoder::new(
                Cursor::new(&mut buffer),
                self.width as u32,
                self.height as u32,
            );
            encoder.set_color(png::ColorType::Rgb);
            encoder.set_depth(png::BitDepth::Sixteen);

            let mut writer = encoder.write_header().map_err(|e| {
                ColorError::Core(rraw_core::CoreError::SerializationError(e.to_string()))
            })?;

            // Convert normalized f32 in [0.0, 1.0] to BigEndian u16 bytes
            let mut raw_bytes = Vec::with_capacity(self.pixels.len() * 3 * 2);
            for &[r, g, b] in &self.pixels {
                let u_r = (r.clamp(0.0, 1.0) * 65535.0).round() as u16;
                let u_g = (g.clamp(0.0, 1.0) * 65535.0).round() as u16;
                let u_b = (b.clamp(0.0, 1.0) * 65535.0).round() as u16;

                raw_bytes.extend_from_slice(&u_r.to_be_bytes());
                raw_bytes.extend_from_slice(&u_g.to_be_bytes());
                raw_bytes.extend_from_slice(&u_b.to_be_bytes());
            }

            writer.write_image_data(&raw_bytes).map_err(|e| {
                ColorError::Core(rraw_core::CoreError::SerializationError(e.to_string()))
            })?;
        }

        Ok(buffer)
    }
}

/// Shared CPU reference photographic pipeline executor.
#[derive(Debug, Default, Clone, Copy)]
pub struct CpuReferencePipeline;

impl CpuReferencePipeline {
    /// Creates a new CPU reference pipeline runner.
    #[must_use]
    pub const fn new() -> Self {
        Self
    }

    /// Executes the complete 5-stage CPU reference pipeline:
    /// 1. Pre-demosaic WB scaling without 1.0 clamp (`sat_c = 1.0 * w_c`).
    /// 2. Bayer demosaicing (reconstructing continuous RGB).
    /// 3. Highlight Reconstruction (HLR) above `sat_c` eliminating magenta casts.
    /// 4. ACEScg AP1 colorimetry & Gamut Guard.
    /// 5. AgX display tone mapping parameterized by headroom `H`.
    pub fn execute(
        &self,
        cfa: &SignedCfaBuffer,
        recipe: &Recipe,
        headroom: f32,
    ) -> Result<CpuRgbImage, ColorError> {
        let width = cfa.width();
        let height = cfa.height();
        let pattern = cfa.pattern();
        let samples = cfa.samples();

        let wb = recipe.stage2_demosaic.wb_multipliers;
        let sat_r = 1.0 * wb.r();
        let sat_g = 1.0 * wb.g();
        let sat_b = 1.0 * wb.b();

        // 1. Pre-demosaic White Balance scaling (signed f32, UNCLAMPED)
        let mut wb_cfa = Vec::with_capacity(samples.len());
        for y in 0..height {
            for x in 0..width {
                let s = samples[y * width + x];
                let mult = match pattern.color_at(x, y) {
                    CfaColor::Red => wb.r(),
                    CfaColor::Green => wb.g(),
                    CfaColor::Blue => wb.b(),
                };
                wb_cfa.push(s * mult);
            }
        }

        // Helper to safely sample wb_cfa with coordinate clamping
        let sample_at = |sx: isize, sy: isize| -> f32 {
            let cx = sx.clamp(0, width as isize - 1) as usize;
            let cy = sy.clamp(0, height as isize - 1) as usize;
            wb_cfa[cy * width + cx]
        };

        // 2 & 3. Demosaic + Highlight Reconstruction
        let mut linear_pixels = Vec::with_capacity(width * height);
        let exposure_scale = 2.0_f32.powf(recipe.stage5_grading.exposure_ev);
        let sat_threshold = 0.99;
        let curves_lut = crate::curves::generate_1d_lut_1024(&recipe.stage5_grading.tone_curves);
        let has_curves = !recipe.stage5_grading.tone_curves.is_identity();

        match pattern {
            CfaPattern::Bayer(origin) => {
                for y in 0..height {
                    let iy = y as isize;
                    let is_red_row = match origin {
                        BayerOrigin::Rggb | BayerOrigin::Grbg => y & 1 == 0,
                        BayerOrigin::Bggr | BayerOrigin::Gbrg => y & 1 != 0,
                    };

                    for x in 0..width {
                        let ix = x as isize;
                        let color = pattern.color_at(x, y);

                        let (mut r, mut g, mut b) = match color {
                            CfaColor::Red => {
                                let r = sample_at(ix, iy);
                                let g = (sample_at(ix - 1, iy)
                                    + sample_at(ix + 1, iy)
                                    + sample_at(ix, iy - 1)
                                    + sample_at(ix, iy + 1))
                                    * 0.25;
                                let b = (sample_at(ix - 1, iy - 1)
                                    + sample_at(ix + 1, iy - 1)
                                    + sample_at(ix - 1, iy + 1)
                                    + sample_at(ix + 1, iy + 1))
                                    * 0.25;
                                (r, g, b)
                            }
                            CfaColor::Blue => {
                                let b = sample_at(ix, iy);
                                let g = (sample_at(ix - 1, iy)
                                    + sample_at(ix + 1, iy)
                                    + sample_at(ix, iy - 1)
                                    + sample_at(ix, iy + 1))
                                    * 0.25;
                                let r = (sample_at(ix - 1, iy - 1)
                                    + sample_at(ix + 1, iy - 1)
                                    + sample_at(ix - 1, iy + 1)
                                    + sample_at(ix + 1, iy + 1))
                                    * 0.25;
                                (r, g, b)
                            }
                            CfaColor::Green => {
                                let g = sample_at(ix, iy);
                                let (r, b) = if is_red_row {
                                    let r = (sample_at(ix - 1, iy) + sample_at(ix + 1, iy)) * 0.5;
                                    let b = (sample_at(ix, iy - 1) + sample_at(ix, iy + 1)) * 0.5;
                                    (r, b)
                                } else {
                                    let b = (sample_at(ix - 1, iy) + sample_at(ix + 1, iy)) * 0.5;
                                    let r = (sample_at(ix, iy - 1) + sample_at(ix, iy + 1)) * 0.5;
                                    (r, b)
                                };
                                (r, g, b)
                            }
                        };

                        // Highlight Reconstruction (HLR) above sat_c:
                        let r_clipped = r >= sat_threshold * sat_r;
                        let g_clipped = g >= sat_threshold * sat_g;
                        let b_clipped = b >= sat_threshold * sat_b;

                        if r_clipped || g_clipped || b_clipped {
                            if !g_clipped {
                                if r_clipped {
                                    r = g.max(sat_threshold * sat_r);
                                }
                                if b_clipped {
                                    b = g.max(sat_threshold * sat_b);
                                }
                            } else if !r_clipped && !b_clipped {
                                let avg_rb = (r + b) * 0.5;
                                g = avg_rb;
                            } else {
                                let max_val = r.max(g).max(b);
                                r = max_val;
                                g = max_val;
                                b = max_val;
                            }
                        }

                        // 4. Colorimetry, Tone Curves & Exposure
                        let exposed = Vec3::new(r, g, b) * exposure_scale;
                        let curved = if has_curves {
                            crate::curves::apply_tone_curves_lut(exposed, &curves_lut)
                        } else {
                            exposed
                        };
                        let guarded = apply_gamut_guard_ap1(curved);
                        linear_pixels.push([guarded.x, guarded.y, guarded.z]);
                    }
                }
            }
            CfaPattern::XTrans(_) => {
                for y in 0..height {
                    let iy = y as isize;
                    for x in 0..width {
                        let ix = x as isize;
                        let s = sample_at(ix, iy);
                        let exposed = Vec3::new(s, s, s) * exposure_scale;
                        let curved = if has_curves {
                            crate::curves::apply_tone_curves_lut(exposed, &curves_lut)
                        } else {
                            exposed
                        };
                        let guarded = apply_gamut_guard_ap1(curved);
                        linear_pixels.push([guarded.x, guarded.y, guarded.z]);
                    }
                }
            }
        }

        // 5. Smart Lighting: scene-aware adaptive local tone mapping in ACEScg AP1
        if recipe.stage5_grading.smart_lighting.is_active() {
            crate::smart_lighting::apply_smart_lighting_acescg(
                &mut linear_pixels,
                width,
                height,
                &recipe.stage5_grading.smart_lighting,
            )?;
        }

        // 6. AgX Display Rendering Transform (DRT)
        let mut demosaiced = Vec::with_capacity(linear_pixels.len());
        for &[r, g, b] in &linear_pixels {
            let drt_r = apply_agx_edr(r, headroom);
            let drt_g = apply_agx_edr(g, headroom);
            let drt_b = apply_agx_edr(b, headroom);
            demosaiced.push([drt_r, drt_g, drt_b]);
        }

        CpuRgbImage::new(width, height, demosaiced)
    }
}
